import fs from 'node:fs';
import vm from 'node:vm';
const LTR_RUN = /[A-Za-z][A-Za-z0-9+.-]*:\/\/[A-Za-z0-9:\/?&=._%+-]*|[A-Za-z0-9][A-Za-z0-9 .,:×x\/()+_-]*[A-Za-z0-9)]|[A-Za-z0-9]/g;
const sandbox={window:{}}; vm.createContext(sandbox);
vm.runInContext(fs.readFileSync('/Users/raedmohammed/RaedWorkoutsV2/worktree-v16/data.js','utf8'), sandbox);
const rw=sandbox.window.RW;
const check=(s,label)=>{
  const runs=[...String(s).matchAll(LTR_RUN)].map(m=>[m.index,m.index+m[0].length,m[0]]);
  for(let i=0;i<runs.length-1;i++){
    const gap=String(s).slice(runs[i][1],runs[i+1][0]);
    if(gap && gap.trim()!=='' && !/[؀-ۿ]/.test(gap)) console.log(label,'|',JSON.stringify(s),'| GAP',JSON.stringify(gap),runs[i][2],runs[i+1][2]);
  }
};
(rw.MOTIVATIONAL_MESSAGES||[]).forEach((m,i)=>check(m,'MOTIV['+i+']'));
for(const e of rw.EXERCISES||[]) { if(e.cue) check(e.cue,'CUE '+e.id); }
for(const [id,m] of Object.entries(rw.MUSCLES||{})) check(m.ar,'MUSCLE '+id);
